Corresponding to the RS scheme's operation of Case II, the probability that $U_1$ is in outage is given by
    \begin{eqnarray}
        P_{\rm out}^{(\rm II)} = e^{\frac{1}{P_1}} \mu\left( \frac{1}{P_1 \eta_0}\right) - e^{-\frac{\varepsilon_0 + \varepsilon_1 + \varepsilon_0 \varepsilon_1}{P_1}} \mu\left( -\frac{P_0}{P_1} \right)    \label{eq:poutII}
    \end{eqnarray}
    with $\eta_0 \triangleq \frac{\varepsilon_0}{P_0}$ and
    \begin{eqnarray}
        \mu(\nu) = \left\{ {\begin{array}{*{20}{c}}
            {\eta_0 \varepsilon_1 }, &{ {\rm if~~} \nu = 0 },\\
            \frac{e^{- \eta_0 (\nu+1) } - e^{- \eta_0 (\nu+1) (1+\varepsilon_1)  }}{ \nu + 1 } , &{\rm otherwise}.
            \end{array}} \right.
    \end{eqnarray}

Corresponding to the RS scheme's operations in Cases I and III, probabilities that $U_1$ is in outage are given by
    \begin{eqnarray}
        P_{\rm out}^{(\rm I)} = e^{-\eta_0} - e^{\frac{1}{P_1}} \mu\left( \frac{1}{P_1 \eta_0}  \right) - e^{-\eta_0(1 + \varepsilon_1) - \eta_1},
    \end{eqnarray}
    \begin{eqnarray}
        P_{\rm out}^{(\rm III)} = 1 - e^{-\eta_0} - \frac{ e^{-\eta_1} (1 - e^{-\eta_0(P_0\eta_1 + 1)}) }{P_0 \eta_1 + 1}  ,
    \end{eqnarray}
    respectively, where $\eta_1 \triangleq \frac{\varepsilon_1}{P_1}$.

The outage probability experienced by the secondary user in the proposed RS scheme is given by
    \begin{eqnarray}
        P_{\rm out} &\!\!\!=\!\!\!& 1 -  e^{-\eta_0(1 + \varepsilon_1) - \eta_1}
         - e^{-\frac{\varepsilon_0 + \varepsilon_1 + \varepsilon_0 \varepsilon_1}{P_1}} \mu\left( - \frac{P_0}{P_1}   \right) \nonumber \\
         &\!\!\! \!\!\!&  - \frac{ e^{-\eta_1} (1 - e^{-\eta_0(P_0\eta_1 + 1)}) }{P_0 \eta_1 + 1}. \label{eq:Pout}
    \end{eqnarray}
